#include <WiFi.h>
#include <WebServer.h>

const char* ssid = "ESP32-BUZZER";
const char* password = "12345678";

#define BUZZER_PIN 25

WebServer server(80);

void beep(int duration) {
  digitalWrite(BUZZER_PIN, HIGH);
  delay(duration);
  digitalWrite(BUZZER_PIN, LOW);
}

void handleRoot() {
  String page = R"rawliteral(
  <!DOCTYPE html>
  <html>
  <head>
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>ESP32 Buzzer</title>
  </head>
  <body style="text-align:center;font-family:Arial">
    <h2>ESP32 BUZZER CONTROL</h2>
    <button onclick="fetch('/short')">Short Beep</button>
    <button onclick="fetch('/long')">Long Beep</button>
    <button onclick="fetch('/double')">Double Beep</button>
  </body>
  </html>
  )rawliteral";

  server.send(200, "text/html", page);
}

void setup() {
  Serial.begin(115200);

  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(BUZZER_PIN, LOW);

  WiFi.softAP(ssid, password);

  server.on("/", handleRoot);

  server.on("/short", []() {
    beep(150);
    server.send(200, "text/plain", "Short beep");
  });

  server.on("/long", []() {
    beep(1000);
    server.send(200, "text/plain", "Long beep");
  });

  server.on("/double", []() {
    beep(150);
    delay(150);
    beep(150);
    server.send(200, "text/plain", "Double beep");
  });

  server.begin();

  Serial.println("WiFi Started!");
  Serial.println(WiFi.softAPIP());
}

void loop() {
  server.handleClient();
}
